selector_to_html = {"a[href=\"#running-playwright-tests\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Running Playwright Tests<a class=\"headerlink\" href=\"#running-playwright-tests\" title=\"Link to this heading\">#</a></h1><p>To run Playwright tests, use the <code class=\"docutils literal notranslate\"><span class=\"pre\">npx</span> <span class=\"pre\">playwright</span> <span class=\"pre\">test</span></code> command, or a package manager script. To avoid opening the interactive html report, use <code class=\"docutils literal notranslate\"><span class=\"pre\">PLAYWRIGHT_HTML_OPEN=never</span></code> environment variable.</p>", "a[href=\"#debugging-playwright-tests\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Debugging Playwright Tests<a class=\"headerlink\" href=\"#debugging-playwright-tests\" title=\"Link to this heading\">#</a></h1><p>To debug a failing Playwright test, run it with <code class=\"docutils literal notranslate\"><span class=\"pre\">--debug=cli</span></code> option. This command will pause the test at the start and print the debugging instructions.</p><p><strong>IMPORTANT</strong>: run the command in the background and check the output until \u201cDebugging Instructions\u201d is printed. Make sure to stop the command after you have finished.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
